import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import {
  projectsKey,
  createProject,
  clientsKey,
  fetchClientOptions,
  PROJECT_STATUSES,
  type ProjectStatus,
} from './queries';

// Add a project for a client. useState holds only what the user is currently entering (CLAUDE.md
// rule 4); the write is a mutation that invalidates ['projects'] so the list refreshes itself.
// The client picker is a <select> whose option values are client ids, read under the shared
// ['clients'] key.
export function ProjectForm() {
  const [name, setName] = useState('');
  const [clientId, setClientId] = useState('');
  const [status, setStatus] = useState<ProjectStatus>('ACTIVE');
  const queryClient = useQueryClient();

  const { data: clients } = useQuery({ queryKey: clientsKey, queryFn: fetchClientOptions });

  const mutation = useMutation({
    mutationFn: createProject,
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: projectsKey });
      setName('');
      setClientId('');
      setStatus('ACTIVE');
    },
  });

  return (
    <form
      data-testid="project-form"
      onSubmit={(event) => {
        event.preventDefault();
        if (name.trim() === '' || clientId === '') {
          return;
        }
        mutation.mutate({ name, clientId: Number(clientId), status });
      }}
    >
      <input
        data-testid="project-form-name"
        placeholder="Name"
        value={name}
        onChange={(event) => setName(event.target.value)}
      />
      <select
        data-testid="project-form-client"
        value={clientId}
        onChange={(event) => setClientId(event.target.value)}
      >
        <option value="">Select a client</option>
        {(clients ?? []).map((client) => (
          <option key={client.id} value={client.id}>
            {client.name}
          </option>
        ))}
      </select>
      <select
        data-testid="project-form-status"
        value={status}
        onChange={(event) => setStatus(event.target.value as ProjectStatus)}
      >
        {PROJECT_STATUSES.map((option) => (
          <option key={option} value={option}>
            {option}
          </option>
        ))}
      </select>
      <button data-testid="project-form-submit" type="submit">
        Add job
      </button>
    </form>
  );
}
import { useQuery } from '@tanstack/react-query';
import {
  projectsKey,
  fetchProjects,
  PROJECTS_SHOW_ARCHIVED_PARAM,
  PROJECTS_TAG_FILTER_PARAM,
  PROJECTS_STATUS_FILTER_PARAM,
} from './queries';
import { ProjectRow } from '../../slots/defs/projectRow';
import { ProjectsToolbar } from '../../slots/defs/projectsToolbar';
import { useSearchParam, asFlag, asNumber, asString } from '../../url/useSearchParam';

// The list. Queries for itself under ['projects'] — never handed its data by a parent (CLAUDE.md
// rule 5). Each row shows the project's name and the client's NAME (from the server-side join).
// Archived projects are tucked away: the toolbar's show-archived toggle owns the `showArchived` URL
// key and the list reads the same key (rule 4), hiding archived rows unless it is on.
export function ProjectsTable() {
  const { data: projects } = useQuery({ queryKey: projectsKey, queryFn: fetchProjects });
  const [showArchived] = useSearchParam(PROJECTS_SHOW_ARCHIVED_PARAM, asFlag);
  const [tagFilter] = useSearchParam(PROJECTS_TAG_FILTER_PARAM, asNumber);
  const [statusFilter] = useSearchParam(PROJECTS_STATUS_FILTER_PARAM, asString);

  if (!projects) {
    return null;
  }

  const visible = projects
    .filter((project) => showArchived || !project.archived)
    .filter((project) => tagFilter === undefined || project.tagIds.includes(tagFilter))
    .filter((project) => statusFilter === '' || project.status === statusFilter);

  if (projects.length === 0) {
    return (
      <>
        <ProjectsToolbar.Slot />
        <p data-testid="projects-empty">No jobs yet.</p>
      </>
    );
  }

  return (
    <>
    <ProjectsToolbar.Slot />
    <table data-testid="projects-table">
      <thead>
        <tr>
          <th>Name</th>
          <th>Client</th>
          <th />
        </tr>
      </thead>
      <tbody>
        {visible.map((project) => (
          <tr key={project.id} data-testid={`project-row-${project.id}`}>
            <td data-testid="project-name">{project.name}</td>
            <td data-testid="project-client">{project.clientName}</td>
            <td>
              <ProjectRow.Slot projectId={project.id} />
            </td>
          </tr>
        ))}
      </tbody>
    </table>
    </>
  );
}
import { getJson, postJson } from '../../api/http';

// Server data under ONE shared key: anything showing projects reads ['projects'], and a write
// invalidates the same key to refresh them all (CLAUDE.md rule 5). A project's row carries its
// client's NAME (the cross-entity join is done server-side, in ProjectView).
export type ProjectView = {
  id: number;
  name: string;
  clientName: string;
  archived: boolean;
  status: ProjectStatus;
  tagIds: number[];
};

// A project's lifecycle status: ACTIVE while worked on, ON_HOLD when paused, FINISHED when done.
// The one list the form's picker offers and the row displays, so both agree without importing.
export type ProjectStatus = 'ACTIVE' | 'ON_HOLD' | 'FINISHED';

export const PROJECT_STATUSES: ProjectStatus[] = ['ACTIVE', 'ON_HOLD', 'FINISHED'];

export const projectsKey = ['projects'] as const;

// The URL search-param key the show-archived toggle owns and the list reads (CLAUDE.md rule 4).
// Shared as a constant so the two files agree on the one key without importing each other.
export const PROJECTS_SHOW_ARCHIVED_PARAM = 'showArchived';

// The URL search-param key the label filter owns and the list reads (CLAUDE.md rule 4): the chosen
// tag id, or absent for "all". Shared as a constant so the two files agree on the one key.
export const PROJECTS_TAG_FILTER_PARAM = 'tag';

// The URL search-param key the status filter owns and the list reads (CLAUDE.md rule 4): the chosen
// lifecycle status (ACTIVE / ON_HOLD / FINISHED), or absent for "all". Shared as a constant so the
// two files agree on the one key without importing each other.
export const PROJECTS_STATUS_FILTER_PARAM = 'status';

// The shared pool of labels, read under the SHARED ['tags'] key (CLAUDE.md rule 5) — the projects
// filter and the project-detail label picker stay in step through the key, without importing each
// other: attaching a label elsewhere invalidates ['tags'] and this select updates itself.
export type TagOption = { id: number; name: string };

export const tagsKey = ['tags'] as const;

export function fetchTagOptions(): Promise<TagOption[]> {
  return getJson<TagOption[]>('/api/tags');
}

export function fetchProjects(): Promise<ProjectView[]> {
  return getJson<ProjectView[]>('/api/projects');
}

export function createProject(
  input: { name: string; clientId: number; status: ProjectStatus },
): Promise<ProjectView> {
  return postJson<ProjectView>('/api/projects', input);
}

/** Delete a project the user no longer needs; the id is in the path, no body needed. */
export function deleteProject(projectId: number): Promise<void> {
  return postJson<void>(`/api/projects/${projectId}/delete`, {});
}

/** Archive (tuck away) a project so it drops off the lists but is retained; id is in the path. */
export function archiveProject(projectId: number): Promise<void> {
  return postJson<void>(`/api/projects/${projectId}/archive`, {});
}

// The client options the form's select needs. Read under the SHARED ['clients'] key (CLAUDE.md
// rule 5) — features never import each other, they stay in step through the key: creating a client
// elsewhere invalidates ['clients'] and this select updates itself.
export type ClientOption = { id: number; name: string };

export const clientsKey = ['clients'] as const;

export function fetchClientOptions(): Promise<ClientOption[]> {
  return getJson<ClientOption[]>('/api/clients');
}

